  "claim": {
    "component_id": "C006.component",
    "value": "The ability to link the records is assumed only provisionally.",
    "scope": "Record linkage used in reconstructing the sampled orders.",
    "provenance": {
      "refs": [
        {
          "source_id": "P005",
          "role": "SUPPORT"
        },
        {
          "source_id": "P001",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P005 explicitly makes record linkability provisional; P001 identifies the sampled orders and documentary traces."
    }
  },
  "signal_basis": {
    "component_id": "C006.signal_basis",
    "value": "Trace approval records through order placement and attachment, testing whether records can be found and linked to the relevant order. These are proposed observations rather than reported findings.",
    "scope": "Record tracing for the 14 flagged orders, with the described signal assumed to occur for this assessment.",
    "provenance": {
      "refs": [
        {
          "source_id": "P007",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans establish the tracing operation, the linkage observation, and its proposed status."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C006.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This component is inapplicable because the judgment is not CONDITIONAL_WARRANT."
    }
  },
  "rationale": "The claim states a bounded working assumption, not an established empirical capability. The mapping explicitly adopts that provisional assumption and tests linkage through record tracing. Within those limits, the operation and signal are consistent with and license the claim without requiring proof that all records are linkable.",
  "uncertainty": "Actual linkage reliability remains to be tested; that uncertainty is expressly preserved by the claim.",
  "anomalies": []
}
